#!/usr/bin/env python3
"""Create self-contained read-only B91 floor/block-level design viewer. No network."""
import json,pathlib
here=pathlib.Path(__file__).resolve().parent
root=here.parents[2]
read=lambda name:json.loads((root/name).read_text(encoding='utf8'))
b66=read('parallel/b66/main/B66_LOCAL_3D_ASSEMBLY.json')
b91=read('parallel/b91/main/B91_FLOOR_BRANCHES_REPORT.json')
by={}
for r in b91['rooms']:by.setdefault(r['sectionId'],[]).append(r)
fl={f['sectionId']:f for f in b91['floors']}
sections=[]
for s in b66['sections']:
 sections.append({'id':s['id'],'floorMaskRows':s['floorMaskRows'],'rooms':s['conceptRooms'],
  'corridors':s['conceptReservations']['corridors'],'stairs':s['conceptReservations']['stairs'],
  'elevators':s['conceptReservations']['elevators'],'held':by.get(s['id'],[]),'branch':fl.get(s['id'])})
data=json.dumps({'sections':sections,'totals':b91['totals'],'patterns':b91['patterns'],'reportSha256':b91['reportSha256']},ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
page=r'''<!doctype html><html lang="ja"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MinecraftAIBuilder B91 オフライン建築変更案</title><style>
:root{color-scheme:dark;background:#0b1423;color:#eaf0f8;font:14px system-ui,'Yu Gothic',sans-serif}body{max-width:1290px;margin:auto;padding:20px;line-height:1.6}h1{font-size:27px;margin:0}h2{font-size:17px;margin:0 0 9px}p,.muted{color:#aabbd1}a{color:#a0cfff}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:10px;margin:16px 0}.metric,.panel{background:#17263a;border:1px solid #314862;border-radius:12px;padding:14px}.metric b{display:block;font-size:26px;color:#fff}select{font:inherit;background:#081c30;border:1px solid #57769b;color:#fff;padding:9px;border-radius:8px}.grid{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(310px,1fr);gap:14px}@media(max-width:830px){.grid{grid-template-columns:1fr}}.line{display:flex;flex-wrap:wrap;gap:13px;align-items:center;margin-bottom:12px}canvas{width:100%;height:auto;image-rendering:pixelated;border-radius:8px;background:#0a1424}.legend{display:flex;flex-wrap:wrap;gap:12px;font-size:12px;margin-bottom:10px}.legend i{display:inline-block;width:12px;height:12px;border-radius:2px;margin-right:4px;vertical-align:middle}.item{background:#0e1e33;border:1px solid #355171;border-radius:9px;padding:11px;margin:9px 0}.hint{font-size:12px;color:#9db1cd}strong{color:#fff}details{margin-top:7px}summary{cursor:pointer;color:#a5d5ff}pre{font-size:11px;line-height:1.4;background:#0a1727;padding:10px;border-radius:8px;white-space:pre-wrap;word-break:break-word;max-height:290px;overflow:auto}.t{font-variant-numeric:tabular-nums}</style></head><body>
<h1>MinecraftAIBuilder B91 — 室内・外殻の3D設計変更案</h1><p>5棟・30階をオフライン表示。34境界をドア空間、横枠、まぐさ、本番ブロック、既存296候補に分けて評価。これは施工図ではありません。</p>
<div class="stats" id="stats"></div><div class="grid"><section class="panel"><div class="line"><label>建物／階 <select id="floor"></select></label><label>強調 <select id="mode"><option value="design">検証候補</option><option value="collision">変更対象ブロック</option><option value="base">元の間取り</option></select></label></div><div class="legend"><span><i style="background:#3485b9"></i>名目廊下</span><span><i style="background:#687c97"></i>一般室</span><span><i style="background:#e36c80"></i>保留室</span><span><i style="background:#ffd067"></i>局所候補（未承認）</span><span><i style="background:#bb7cf2"></i>変更が必要な本番ブロック</span><span><i style="background:#5cdaa3"></i>階段・昇降機予約</span></div><canvas id="map" width="910" height="740"></canvas><p class="hint" id="summary"></p><p class="hint">候補があってもドアの開閉・旧開口閉鎖・階段到達性は検証されていません。本番ブロックは変更していません。</p></section><aside class="panel"><h2>保留室・変更要求</h2><div id="details"></div></aside></div>
<section class="panel" style="margin-top:14px"><h2>4パターンの階別再設計条件</h2><div id="patterns"></div></section><p class="hint">NOT_PREPARED / 施工前9ゲートBLOCKED / BuildPlan.operations=[] / worldContacts=0 / 既存296室は未承認のまま</p>
<script>const D=__DATA__,el=id=>document.getElementById(id),esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const t=D.totals;for(const [label,n] of [['既存の未承認候補',t.previousUnapprovedCandidates],['保留室',t.originalHeldRooms],['3D設計境界',t.inspectedArchitecturalBranches],['階内で重複なしの局所案',t.collisionFreeWholeFloorSelections],['新規承認室',t.newlyApprovedRooms]])el('stats').insertAdjacentHTML('beforeend',`<div class="metric"><b class="t">${n}</b><span class="hint">${label}</span></div>`);
for(const s of D.sections){let o=document.createElement('option');o.value=s.id;o.textContent=s.id;el('floor').appendChild(o)}el('floor').value='apartment/candidate-01/L2';
function draw(){const s=D.sections.find(x=>x.id===el('floor').value);if(!s)return;const ctx=el('map').getContext('2d'),w=s.floorMaskRows[0].length,h=s.floorMaskRows.length,c=Math.min(32,Math.floor(Math.min(875/w,705/h))),ox=Math.floor((910-w*c)/2),oz=Math.floor((740-h*c)/2),mode=el('mode').value;ctx.fillStyle='#071222';ctx.fillRect(0,0,910,740);
const fill=(p,color)=>{ctx.fillStyle=color;ctx.fillRect(ox+p.x*c+1,oz+p.z*c+1,c-2,c-2)};
for(let z=0;z<h;z++)for(let x=0;x<w;x++)fill({x,z},s.floorMaskRows[z][x]==='1'?'#1a2b43':'#0b1526');s.corridors.forEach(p=>fill(p,'#3485b9'));for(const r of s.rooms)for(let z=r.z;z<r.z+r.depth;z++)for(let x=r.x;x<r.x+r.width;x++)fill({x,z},'#687c97');
for(const r of s.held){const rect=s.rooms.find(v=>v.id===r.roomId);if(!rect)continue;for(let z=rect.z;z<rect.z+rect.depth;z++)for(let x=rect.x;x<rect.x+rect.width;x++)fill({x,z},'#e36c80');if(mode!=='base')for(const a of r.apertures){fill(a.doorRoomCell,'#ffd067');if(mode==='collision')for(const p of a.explicitBlockChangeRequests)fill(p,'#bb7cf2')}}[...s.stairs,...s.elevators].forEach(p=>fill(p,'#5cdaa3'));
ctx.font=`${Math.max(9,Math.floor(c*.38))}px ui-monospace,monospace`;ctx.textAlign='center';ctx.textBaseline='middle';for(const r of s.rooms){ctx.fillStyle='#fff';ctx.fillText(r.id.split('-R').pop(),ox+(r.x+r.width/2)*c,oz+(r.z+r.depth/2)*c)}
const arb=s.branch?.arbitration;el('summary').textContent=`${s.id} · ${s.rooms.length}名目室 · 保留${s.held.length}室 · 階内で重複なしの局所案${arb?.reviewOnlyAlternatives.length||0}件（未承認）`;
el('details').innerHTML=s.held.length?s.held.map(r=>{const good=r.apertures.filter(a=>!a.geometryFailures.length),changes=r.apertures.reduce((n,a)=>n+a.productionContacts,0);return `<article class="item"><strong>${esc(r.roomId)}</strong> · ${esc(r.pattern.split('/').at(-1))}<div class="hint">元の面積 ${r.roomArea}セル（維持）、3D検証候補 ${r.apertures.length}、衝突のない局所形状 ${good.length}、ブロック変更要求 ${changes}件（未承認）</div>${r.apertures.slice(0,3).map(a=>`<div class="hint">開口 ${a.doorRoomCell.x},${a.doorRoomCell.z} ｜ ${esc(a.branchClass)} ｜ 主な保留：${esc(a.geometryFailures.join('、')||'設計承認・避難動線')}</div>`).join('')||'<div class="hint">候補境界なし。区画全体の再設計が必要です。</div>'}<details><summary>3D部材・既存ブロックの根拠を見る</summary><pre>${esc(JSON.stringify(r.apertures,null,2))}</pre></details></article>`}).join(''):'この階にB91保留対象はありません。';}
el('floor').addEventListener('change',draw);el('mode').addEventListener('change',draw);draw();el('patterns').innerHTML=D.patterns.map(p=>`<article class="item"><strong>${esc(p.pattern)}</strong> ${p.roomCount}室・検査した境界 ${p.scanned3dArchitecturalVariants}<div class="hint">候補境界なし ${p.roomsWithoutAnyFrontier}室 / 既存ブロック変更なし局所案 ${p.roomsWithFullyClearApertureReview}室 / 新規承認 0室</div></article>`).join('');
</script></body></html>'''
page=page.replace('__DATA__',data)
(here/'B91_FLOOR_BRANCHES_REVIEW.html').write_text(page,encoding='utf8')
print('B91 viewer',len(page.encode()),'bytes, floors',len(sections))
